public class ShoppingCartTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static double round2(double v) {
        return Math.round(v * 100.0) / 100.0;
    }

    public static void main(String[] args) {
        ShoppingCart cart = new ShoppingCart();
        check("empty cart itemCount", 0, cart.itemCount());
        check("empty cart total", 0.0, round2(cart.total()));

        cart.add("Apple", 0.5, 4);
        check("one line, qty 4", 4, cart.itemCount());
        check("total after apples (2dp)", 2.0, round2(cart.total()));

        cart.add("Bread", 2.25, 2);
        cart.add("Milk", 1.99, 3);
        check("itemCount sums quantities", 9, cart.itemCount());
        check("total 2.0 + 4.5 + 5.97 (2dp)", 12.47, round2(cart.total()));

        cart.add("Apple", 0.5, 1);
        check("same product twice is fine", 10, cart.itemCount());
        check("total after one more apple (2dp)", 12.97, round2(cart.total()));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

