import java.util.ArrayList;

record CartItem(String name, double price, int qty) { }

public class ShoppingCart {

    private final ArrayList<CartItem> items = new ArrayList<>();

    public void add(String name, double price, int qty) {
        items.add(new CartItem(name, price, qty));
    }

    public int itemCount() {
        int count = 0;
        for (CartItem item : items) {
            count += item.qty();
        }
        return count;
    }

    public double total() {
        double sum = 0.0;
        for (CartItem item : items) {
            sum += item.price() * item.qty();
        }
        return sum;
    }
}
